13	// Destination chains are arbitrary byte strings: the Go submit interface only
14	// requires a non-empty destination, never valid UTF-8 — text, colons, NUL
15	// bytes, stray 0xFF/0xFE bytes, or text mixed with them. The destination is
16	// half of the replay identity (source, destination, nonce), so it must survive
17	// save, reopen and compaction byte for byte; JSON string encoding would
18	// otherwise silently rewrite invalid bytes to U+FFFD, merging distinct
19	// destinations and misattributing consumed nonces after a restart.
20	
21	const replacementCharTo = "�"
22	
23	// toEnvelope builds an envelope addressed to destination to, source chain-a,
24	// with caller-chosen id/nonce/proof height.
25	func toEnvelope(id, to string, nonce uint64, proofAt int64) Envelope {
