84	// 0xFF, 0xFE and the legal character U+FFFD are three different destinations:
85	// with the same source and nonce, all three messages succeed independently and
86	// consume three distinct triples. They must stay distinct across a plain
87	// reopen, further processing, and a forced compaction plus reopen; saved and
88	// recovered successes must never merge.
89	func TestDestinationInvalidBytesDistinctConsumptionAcrossReopens(t *testing.T) {
90		toFF := string([]byte{0xFF})
91		toFE := string([]byte{0xFE})
92		toFD := replacementCharTo
93	
94		setup := func(t *testing.T, dir string) *Queue {
95			t.Helper()
96			q, err := Open(dir)
97			if err != nil {
98				t.Fatal(err)
99			}
100			if err := q.RegisterSource("chain-a"); err != nil {
101				t.Fatal(err)
102			}
103			if err := q.UpsertHeader(Header{Chain: "chain-a", Height: 100, Root: "r", Trusted: true}); err != nil {
104				t.Fatal(err)
105			}
106			// Same source and nonce 7; only the destination distinguishes them.
107			for _, e := range []Envelope{
108				toEnvelope("ff", toFF, 7, 100),
109				toEnvelope("fe", toFE, 7, 100),
110				toEnvelope("fd", toFD, 7, 100),
111			} {
112				if _, err := q.Submit(e); err != nil {
113					t.Fatalf("submit to % x: %v", e.Message.To, err)
114				}
115			}
116			rep, err := q.Advance(1000)
117			if err != nil {
118				t.Fatal(err)
119			}
120			if len(rep.Results) != 3 {
121				t.Fatalf("three distinct destinations must each succeed: %+v", rep.Results)
122			}
123			for _, r := range rep.Results {
124				if r.Status != StatusSuccess {
125					t.Fatalf("message %s to a distinct destination must succeed, got %s (%s)", r.ID, r.Status, r.Reason)
126				}
127			}
128			if len(q.consumed) != 3 {
129				t.Fatalf("want three distinct consumed triples, got %d: %v", len(q.consumed), q.consumed)
130			}
131			return q
132		}
133	
134		// assertRestored verifies the three winners after every reopen boundary.
135		assertRestored := func(t *testing.T, q *Queue) {
136			t.Helper()
137			for id, to := range map[string]string{"ff": toFF, "fe": toFE, "fd": toFD} {
138				qy, ok := q.Query(id)
139				if !ok {
140					t.Fatalf("winner %s vanished", id)
141				}
142				if !bytes.Equal([]byte(qy.To), []byte(to)) {
143					t.Fatalf("destination of %s changed: want % x got % x", id, to, qy.To)
144				}
145				if qy.Status != StatusSuccess || qy.Attempts != 1 {
146					t.Fatalf("winner %s not restored as success: %+v", id, qy)
147				}
148				if winner := q.consumed[newConsumeToken("chain-a", to, 7)]; winner != id {
149					t.Fatalf("consumption of destination % x misattributed to %q", to, winner)
150				}
151			}
152		}
153	
154		dir := t.TempDir()
155		q := setup(t, dir)
156		if err := q.Close(); err != nil {
157			t.Fatal(err)
158		}
159	
160		// Plain reopen: the three consumed triples stay distinct and byte-exact.
161		q = reopen(t, dir)
162		assertRestored(t, q)
163	
164		// New ids on the already-consumed destinations replay, each attributed to
165		// the real winner; a new destination that never consumed nonce 7 delivers
166		// instead of being misjudged as a replay.
167		for _, c := range []struct {
168			id, to, winner string
169		}{
170			{"again-ff", toFF, "ff"},
171			{"again-fe", toFE, "fe"},
172			{"again-fd", toFD, "fd"},
173		} {
174			if _, err := q.Submit(toEnvelope(c.id, c.to, 7, 100)); err != nil {
175				t.Fatal(err)
176			}
177		}
178		if _, err := q.Submit(toEnvelope("again-other", "chain-other", 7, 100)); err != nil {
179			t.Fatal(err)
180		}
181		rep, err := q.Advance(2000)
182		if err != nil {
183			t.Fatal(err)
184		}
185		got := map[string]Result{}
186		for _, r := range rep.Results {
187			got[r.ID] = r
188		}
189		for _, c := range []struct {
190			id, to, winner string
191		}{
192			{"again-ff", toFF, "ff"},
193			{"again-fe", toFE, "fe"},
194			{"again-fd", toFD, "fd"},
195		} {
196			r := got[c.id]
197			wantReason := "nonce combination already consumed by message " + c.winner
198			if r.Status != StatusReplay || r.Reason != wantReason {
199				t.Fatalf("%s (to % x) must replay at %s: %+v", c.id, c.to, c.winner, r)
200			}
201		}
202		if r := got["again-other"]; r.Status != StatusSuccess {
203			t.Fatalf("a destination that never consumed nonce 7 must deliver, not replay: %+v", r)
204		}
205		if len(q.consumed) != 4 {
206			t.Fatalf("want four consumed triples after the fresh delivery: %v", q.consumed)
207		}
208		if err := q.Close(); err != nil {
209			t.Fatal(err)
210		}
211	
212		// Reopen after the replay/success processing: attributions survive.
213		q = reopen(t, dir)
214		assertRestored(t, q)
215		for _, c := range []struct{ id, winner string }{
216			{"again-ff", "ff"}, {"again-fe", "fe"}, {"again-fd", "fd"},
217		} {
218			if qy, ok := q.Query(c.id); !ok || qy.Status != StatusReplay ||
219				qy.Reason != "nonce combination already consumed by message "+c.winner {
220				t.Fatalf("%s replay record lost/misattributed: ok=%v %+v", c.id, ok, qy)
221			}
222		}
223		if qy, ok := q.Query("again-other"); !ok || qy.Status != StatusSuccess {
224			t.Fatalf("fresh-destination delivery lost: ok=%v %+v", ok, qy)
225		}
226	
227		// Forced compaction plus another reopen must merge nothing.
228		if err := q.store.compact(q.snapshot()); err != nil {
229			t.Fatalf("compact: %v", err)
230		}
231		if err := q.Close(); err != nil {
232			t.Fatal(err)
233		}
234		q = reopen(t, dir)
235		defer q.Close()
236		assertRestored(t, q)
237		if len(q.consumed) != 4 {
238			t.Fatalf("compaction merged consumed triples: %v", q.consumed)
239		}
240		// Post-compaction the replay rules still hold by exact destination bytes.
241		if _, err := q.Submit(toEnvelope("post-ff", toFF, 7, 100)); err != nil {
242			t.Fatal(err)
243		}
244		if _, err := q.Submit(toEnvelope("post-other", "chain-other-2", 7, 100)); err != nil {
245			t.Fatal(err)
246		}
247		rep, err = q.Advance(3000)
248		if err != nil {
249			t.Fatal(err)
250		}
251		for _, r := range rep.Results {
252			switch r.ID {
253			case "post-ff":
254				if r.Status != StatusReplay || r.Reason != "nonce combination already consumed by message ff" {
255					t.Fatalf("post-compaction replay misattributed: %+v", r)
256				}
257			case "post-other":
258				if r.Status != StatusSuccess {
259					t.Fatalf("fresh destination post-compaction must deliver: %+v", r)
260				}
261			}
262		}
263	}
