271		toRaw := "w" + string([]byte{0x00, 0xFF, 0xFE})
272		env := toEnvelope("w", toRaw, 7, 100) // trusted coverage stops at 100 below
273	
274		dir := t.TempDir()
275		q, err := Open(dir)
276		if err != nil {
277			t.Fatal(err)
278		}
279		q.RegisterSource("chain-a")
280		if _, err := q.Submit(env); err != nil {
281			t.Fatal(err)
282		}
