284			t.Fatal(err)
285		}
286		if st, _ := q.Query("w"); st.Status != StatusWaiting || st.Attempts != 1 || st.NextRetry != 2000 {
287			t.Fatalf("setup: unexpected state %+v", st)
288		}
289		if err := q.Close(); err != nil {
290			t.Fatal(err)
291		}
292	
293		q = reopen(t, dir)
294		defer q.Close()
295		echo, err := q.Submit(env)
296		if err != nil {
297			t.Fatalf("byte-identical resubmit after reopen must return the existing record: %v", err)
298		}
299		if !bytes.Equal([]byte(echo.Msg.Message.To), []byte(toRaw)) ||
300			echo.Status != StatusWaiting || echo.Attempts != 1 || echo.NextRetry != 2000 {
301			t.Fatalf("resubmit must not reschedule or rewrite destination: %+v", echo)
302		}
303		if len(q.Queries()) != 1 {
304			t.Fatal("identical resubmit must not add a record")
305		}
306	
307		for name, bad := range map[string]string{
308			"one byte changed":    "w" + string([]byte{0x00, 0xFF, 0x00}),
309			"single invalid byte": string([]byte{0xFE}),
310			"look-alike U+FFFD":   replacementCharTo,
311			"mixed but replaced":  "w" + string([]byte{0x00, 0xEF, 0xBF, 0xBD}) + string([]byte{0xFE}),
312		} {
313			if _, err := q.Submit(toEnvelope("w", bad, 7, 100)); !errors.Is(err, ErrConflict) {
314				t.Fatalf("%s: destination % x must conflict, got %v", name, bad, err)
315			}
316		}
317		st, _ := q.Query("w")
318		if !bytes.Equal([]byte(st.To), []byte(toRaw)) ||
319			st.Attempts != 1 || st.NextRetry != 2000 || st.Status != StatusWaiting {
320			t.Fatalf("conflicting resubmits changed the original record: %+v", st)
321		}
322	}
