386		raw = append(raw, encodeFrame(mustMarshal(&logEntry{T: kindVersion, V: currentLogV}))...)
387		raw = append(raw, encodeFrame(mustMarshal(&logEntry{
388			T: kindSubmit, Seq: 0, ID: "txt", From: "a", To: "b", Nonce: 1,
389			Payload: "p", ProofAt: 10,
390		}))...)
391		// An old build that lost the invalid bytes saved the destination as U+FFFD.
392		raw = append(raw, encodeFrame(mustMarshal(&logEntry{
393			T: kindSubmit, Seq: 1, ID: "lost", From: "a", To: replacementCharTo, Nonce: 2,
394			Payload: "p", ProofAt: 10,
395		}))...)
396		writeRawLog(t, dir, raw)
397	
398		q := reopen(t, dir)
399		defer q.Close()
400		if got, ok := q.Query("txt"); !ok || got.To != "b" {
401			t.Fatalf("legacy text destination: ok=%v %q", ok, got.To)
402		}
403		got, ok := q.Query("lost")
404		if !ok || !bytes.Equal([]byte(got.To), []byte(replacementCharTo)) {
405			t.Fatalf("legacy replacement destination must be read at face value: ok=%v % x", ok, got.To)
406		}
407		saved := Envelope{Message: Message{
408			ID: "lost", From: "a", To: replacementCharTo, Nonce: 2, Payload: "p", ProofAt: 10,
