528			"submit with both to and toB64": submitBoth,
529			"submit with undecodable toB64": submitBad,
530		} {
531			t.Run(name, func(t *testing.T) {
532				dir := t.TempDir()
533				var data []byte
534				data = append(data, logMagic...)
535				data = append(data, encodeFrame(mustMarshal(&logEntry{T: kindVersion, V: currentLogV}))...)
536				data = append(data, encodeFrame(mustMarshal(e))...)
537				writeRawLog(t, dir, data)
538				assertCorruptAndUntouched(t, dir, data)
539			})
540		}
541		for name, build := range map[string]func() []*logEntry{
542			"success with both consumeTo forms":     successBoth,
543			"success with undecodable consumeToB64": successBadTo,
544			"success whose consumeTo mismatches to": successMismatch,
545		} {
546			t.Run(name, func(t *testing.T) {
547				dir := t.TempDir()
548				var data []byte
549				data = append(data, logMagic...)
550				data = append(data, encodeFrame(mustMarshal(&logEntry{T: kindVersion, V: currentLogV}))...)
551				for _, e := range build() {
552					data = append(data, encodeFrame(mustMarshal(e))...)
553				}
554				writeRawLog(t, dir, data)
555				assertCorruptAndUntouched(t, dir, data)
556			})
557		}
558		for name, jsonBody := range rawCases {
559			t.Run(name, func(t *testing.T) {
560				dir := t.TempDir()
561				var data []byte
562				data = append(data, logMagic...)
563				data = append(data, encodeFrame(mustMarshal(&logEntry{T: kindVersion, V: currentLogV}))...)
564				data = append(data, encodeFrame([]byte(jsonBody))...)
565				writeRawLog(t, dir, data)
566				assertCorruptAndUntouched(t, dir, data)
567			})
568		}
569	}
570	
571	// The empty destination stays rejected by the Go API as an invalid argument.
572	func TestDestinationEmptyStillRejected(t *testing.T) {
573		q, _ := openTempQueue(t)
574		defer q.Close()
575		_, err := q.Submit(Envelope{Message: Message{ID: "m", From: "a", To: "", Nonce: 1, ProofAt: 1}})
576		if !errors.Is(err, ErrInvalidArg) {
577			t.Fatalf("empty destination: want ErrInvalidArg, got %v", err)
578		}
579	}
580	
581	// Automatic threshold compaction, triggered by an ordinary Submit, must carry
582	// invalid-UTF-8 destinations byte-exactly into the snapshot: an oversized
583	// raw-bytes destination supplies the bulk, the small crossing submit pushes
584	// past 4 MiB, and both read identically, in order, after reopen.
585	func TestDestinationInvalidBytesSurviveAutomaticCompaction(t *testing.T) {
586		const margin int64 = 4096
587	
588		versionFrame := int64(len(encodeFrame(mustMarshal(&logEntry{T: kindVersion, V: currentLogV}))))
589		baseSize := int64(len(logMagic)) + versionFrame
590		checkpointFrame := int64(len(encodeFrame(mustMarshal(&logEntry{T: kindAdvance, Now: 1000}))))
591	
592		crossTo := "cross" + string([]byte{0xFF})
593		crossEntry := &logEntry{T: kindSubmit, Seq: 1, ID: "cross", From: "chain-a", Nonce: 2, ProofAt: 1}
594		crossEntry.setTo(crossTo)
595		crossFrame := int64(len(encodeFrame(mustMarshal(crossEntry))))
596	
597		// The filler is the seq-0 submit: its seq zero-value is JSON-omitted. The
598		// gauge entry mirrors the real write field-for-field (id included), so its
599		// framed size is exactly what the real queue appends; only the destination
600		// length varies.
601		fillerFrame := func(toLen int) int64 {
602			e := &logEntry{T: kindSubmit, ID: "filler", From: "chain-a", Nonce: 1, ProofAt: 1}
603			e.setTo(strings.Repeat("\xff", toLen))
604			return int64(len(encodeFrame(mustMarshal(e))))
605		}
606		overhead := fillerFrame(1) - int64(base64.StdEncoding.EncodedLen(1))
607	
608		nCheckpoints := int(margin/checkpointFrame) + 2
609		targetFillerFrame := compactThreshold - margin - baseSize -
610			int64(nCheckpoints)*checkpointFrame - crossFrame
611		if targetFillerFrame <= overhead {
612			t.Fatalf("setup arithmetic leaves no room: target=%d overhead=%d", targetFillerFrame, overhead)
613		}
614		var fillerLen int
615		for lo, hi := 0, int(targetFillerFrame); ; {
616			mid := (lo + hi + 1) / 2
617			if fillerFrame(mid) <= targetFillerFrame {
618				lo = mid
619			} else {
620				hi = mid - 1
621			}
622			if lo == hi {
623				fillerLen = lo
624				break
625			}
626		}
627		if fillerLen == 0 {
628			t.Fatal("filler destination length resolved to zero")
629		}
630		fillerTo := strings.Repeat("\xff", fillerLen)
631		filler := Envelope{Message: Message{ID: "filler", From: "chain-a", To: fillerTo, Nonce: 1, ProofAt: 1}}
632		cross := Envelope{Message: Message{ID: "cross", From: "chain-a", To: crossTo, Nonce: 2, ProofAt: 1}}
633	
634		dir := t.TempDir()
635		q, err := Open(dir)
636		if err != nil {
637			t.Fatal(err)
638		}
639		defer q.Close()
640		if q.store.size != baseSize {
641			t.Fatalf("base size mismatch: want %d got %d", baseSize, q.store.size)
642		}
643		// Equal-time checkpoint padding (legal with no messages yet) so the
644		// crossing submit is exactly what trips 4 MiB; snapshots drop the
645		// checkpoints, so the compacted log lands margin below the threshold.
646		for i := 0; i < nCheckpoints; i++ {
647			if _, err := q.Advance(1000); err != nil {
648				t.Fatal(err)
649			}
650		}
651		if q.store.size > compactThreshold {
652			t.Fatalf("padding crossed the threshold early: %d", q.store.size)
653		}
654		if _, err := q.Submit(filler); err != nil {
655			t.Fatalf("filler submit: %v", err)
656		}
657		if q.store.size > compactThreshold {
658			t.Fatalf("filler crossed before the crossing submit: %d", q.store.size)
659		}
660		if _, err := q.Submit(cross); err != nil {
661			t.Fatalf("crossing submit: %v", err)
662		}
663		if q.store.size > compactThreshold {
664			t.Fatalf("auto-compaction did not shrink the log: %d", q.store.size)
665		}
666		if err := q.Close(); err != nil {
667			t.Fatal(err)
668		}
669	
670		q = reopen(t, dir)
671		defer q.Close()
672		got, ok := q.Query("filler")
673		if !ok || !bytes.Equal([]byte(got.To), []byte(fillerTo)) {
674			t.Fatalf("filler destination changed across auto compaction: ok=%v len(want)=%d len(got)=%d",
675				ok, len(fillerTo), len(got.To))
676		}
677		if got, ok := q.Query("cross"); !ok || !bytes.Equal([]byte(got.To), []byte(crossTo)) {
678			t.Fatalf("crossing destination lost across auto compaction: ok=%v % x", ok, got.To)
679		}
680		all := q.Queries()
681		if len(all) != 2 || all[0].ID != "filler" || all[1].ID != "cross" {
682			t.Fatalf("order after auto compaction: %+v", all)
683		}
684		// Byte-identical resubmits stay idempotent against the compacted records,
685		// and the visually similar replacement character still conflicts.
686		if _, err := q.Submit(filler); err != nil {
687			t.Fatalf("filler identical resubmit after compaction: %v", err)
688		}
689		bad := cross
690		bad.Message.To = replacementCharTo
691		if _, err := q.Submit(bad); !errors.Is(err, ErrConflict) {
692			t.Fatalf("U+FFFD must differ from the invalid-byte destination after compaction: %v", err)
693		}
694		if len(q.Queries()) != 2 {
695			t.Fatal("idempotent/conflicting resubmits changed record count")
696		}
697	
698		raw, err := os.ReadFile(filepath.Join(dir, logName))
699		if err != nil {
700			t.Fatal(err)
701		}
702		if !bytes.Contains(raw, []byte(`"toB64":"`)) {
703			t.Fatalf("invalid destinations not stored byte-exactly: %s", raw[:200])
704		}
705	}
